<?php
 class EnvironmentTest extends PHPUnit_Framework_TestCase { public function setUp() { $_SERVER['DOCUMENT_ROOT'] = '/var/www'; $_SERVER['SCRIPT_FILENAME'] = '/var/www/foo/index.php'; $_SERVER['SERVER_NAME'] = 'slim'; $_SERVER['SERVER_PORT'] = '80'; $_SERVER['SCRIPT_NAME'] = '/foo/index.php'; $_SERVER['REQUEST_URI'] = '/foo/index.php/bar/xyz'; $_SERVER['PATH_INFO'] = '/bar/xyz'; $_SERVER['REQUEST_METHOD'] = 'GET'; $_SERVER['QUERY_STRING'] = 'one=1&two=2&three=3'; $_SERVER['HTTPS'] = ''; $_SERVER['REMOTE_ADDR'] = '127.0.0.1'; unset($_SERVER['CONTENT_TYPE'], $_SERVER['CONTENT_LENGTH']); } public function testMockEnvironment() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PUT' )); $env2 = \Slim\Environment::getInstance(); $this->assertSame($env, $env2); $this->assertInstanceOf('\Slim\Environment', $env); $this->assertEquals('PUT', $env['REQUEST_METHOD']); $this->assertEquals(80, $env['SERVER_PORT']); $this->assertNull($env['foo']); } public function testSetsHttpMethod() { $env = \Slim\Environment::getInstance(true); $this->assertEquals('GET', $env['REQUEST_METHOD']); } public function testParsesPathsWithoutUrlRewriteInSubdirectory() { $env = \Slim\Environment::getInstance(true); $this->assertEquals('/bar/xyz', $env['PATH_INFO']); $this->assertEquals('/foo/index.php', $env['SCRIPT_NAME']); } public function testParsesPathsWithoutUrlRewriteInRootDirectory() { $_SERVER['SCRIPT_FILENAME'] = '/var/www/index.php'; $_SERVER['REQUEST_URI'] = '/index.php/bar/xyz'; $_SERVER['SCRIPT_NAME'] = '/index.php'; $env = \Slim\Environment::getInstance(true); $this->assertEquals('/bar/xyz', $env['PATH_INFO']); $this->assertEquals('/index.php', $env['SCRIPT_NAME']); } public function testParsesPathsWithoutUrlRewriteInRootDirectoryForAppRootUri() { $_SERVER['SCRIPT_FILENAME'] = '/var/www/index.php'; $_SERVER['REQUEST_URI'] = '/index.php'; $_SERVER['SCRIPT_NAME'] = '/index.php'; unset($_SERVER['PATH_INFO']); $env = \Slim\Environment::getInstance(true); $this->assertEquals('/', $env['PATH_INFO']); $this->assertEquals('/index.php', $env['SCRIPT_NAME']); } public function testParsesPathsWithUrlRewriteInSubdirectory() { $_SERVER['SCRIPT_NAME'] = '/foo/index.php'; $_SERVER['REQUEST_URI'] = '/foo/bar/xyz'; unset($_SERVER['PATH_INFO']); $env = \Slim\Environment::getInstance(true); $this->assertEquals('/bar/xyz', $env['PATH_INFO']); $this->assertEquals('/foo', $env['SCRIPT_NAME']); } public function testParsesPathsWithUrlRewriteInRootDirectory() { $_SERVER['SCRIPT_FILENAME'] = '/var/www/index.php'; $_SERVER['SCRIPT_NAME'] = '/index.php'; $_SERVER['REQUEST_URI'] = '/bar/xyz'; unset($_SERVER['PATH_INFO']); $env = \Slim\Environment::getInstance(true); $this->assertEquals('/bar/xyz', $env['PATH_INFO']); $this->assertEquals('', $env['SCRIPT_NAME']); } public function testParsesPathsWithUrlRewriteInRootDirectoryForAppRootUri() { $_SERVER['SCRIPT_FILENAME'] = '/var/www/index.php'; $_SERVER['REQUEST_URI'] = '/'; $_SERVER['SCRIPT_NAME'] = '/index.php'; unset($_SERVER['PATH_INFO']); $env = \Slim\Environment::getInstance(true); $this->assertEquals('/', $env['PATH_INFO']); $this->assertEquals('', $env['SCRIPT_NAME']); } public function testParsesQueryString() { $env = \Slim\Environment::getInstance(true); $this->assertEquals('one=1&two=2&three=3', $env['QUERY_STRING']); } public function testRemovesQueryStringFromPathInfo() { $_SERVER['SCRIPT_NAME'] = '/foo/index.php'; $_SERVER['REQUEST_URI'] = '/foo/bar/xyz?one=1&two=2&three=3'; unset($_SERVER['PATH_INFO']); $env = \Slim\Environment::getInstance(true); $this->assertEquals('/bar/xyz', $env['PATH_INFO']); } public function testPathInfoRetainsUrlEncodedCharacters() { $_SERVER['SCRIPT_FILENAME'] = '/var/www/index.php'; $_SERVER['SCRIPT_NAME'] = '/index.php'; $_SERVER['REQUEST_URI'] = '/foo/%23bar'; $env = \Slim\Environment::getInstance(true); $this->assertEquals('/foo/%23bar', $env['PATH_INFO']); } public function testParsesQueryStringThatDoesNotExist() { unset($_SERVER['QUERY_STRING']); $env = \Slim\Environment::getInstance(true); $this->assertEquals('', $env['QUERY_STRING']); } public function testServerNameIsNotEmpty() { $env = \Slim\Environment::getInstance(true); $this->assertFalse(empty($env['SERVER_NAME'])); } public function testServerPortIsNotEmpty() { $env = \Slim\Environment::getInstance(true); $this->assertFalse(empty($env['SERVER_PORT'])); } public function testUnsetsContentTypeAndContentLength() { $_SERVER['HTTP_CONTENT_LENGTH'] = 150; $env = \Slim\Environment::getInstance(true); $this->assertFalse(isset($env['HTTP_CONTENT_LENGTH'])); } public function testSetsSpecialHeaders() { $_SERVER['CONTENT_TYPE'] = 'text/csv'; $_SERVER['CONTENT_LENGTH'] = '100'; $_SERVER['HTTP_X_REQUESTED_WITH'] = 'XmlHttpRequest'; $env = \Slim\Environment::getInstance(true); $this->assertEquals('text/csv', $env['CONTENT_TYPE']); $this->assertEquals('100', $env['CONTENT_LENGTH']); $this->assertEquals('XmlHttpRequest', $env['HTTP_X_REQUESTED_WITH']); } public function testSetsHttpMethodOverrideHeader() { $_SERVER['HTTP_X_HTTP_METHOD_OVERRIDE'] = 'DELETE'; $env = \Slim\Environment::getInstance(true); $this->assertEquals('DELETE', $env['HTTP_X_HTTP_METHOD_OVERRIDE']); } public function testHttps() { $_SERVER['HTTPS'] = 1; $env = \Slim\Environment::getInstance(true); $this->assertEquals('https', $env['slim.url_scheme']); } public function testNotHttps() { $_SERVER['HTTPS'] = ''; $env = \Slim\Environment::getInstance(true); $this->assertEquals('http', $env['slim.url_scheme']); } public function testNotHttpsIIS() { $_SERVER['HTTPS'] = 'off'; $env = \Slim\Environment::getInstance(true); $this->assertEquals('http', $env['slim.url_scheme']); } public function testInputIsEmptyString() { $env = \Slim\Environment::getInstance(true); $this->assertEquals('', $env['slim.input']); } public function testErrorResource() { $env = \Slim\Environment::getInstance(true); $this->assertTrue(is_resource($env['slim.errors'])); } } 